    def _handle_aliases(cls, values: Dict[str, Any]) -> Dict[str, Any]:
        alias_map = {
            "deviceId": "device_id",
            "id": "device_id",
            "temp": "temperature",
        }
        for alt_key, canonical_key in alias_map.items():
            if alt_key in values:
                # Prefer an explicitly provided canonical key if both exist
                if canonical_key not in values:
                    values[canonical_key] = values.pop(alt_key)
                else:
                    values.pop(alt_key)
        return values


