from pydantic import BaseModel, AfterValidator, BeforeValidator, ConfigDict


def _slug_before(value: str) -> str:
    """Strip surrounding whitespace and lowercase the string before validation."""
    if isinstance(value, str):
        return value.strip().lower()
    return value


def _slug_after(value: str) -> str:
    """Reject empty strings or strings containing spaces after preprocessing."""
    if not value or " " in value:
        raise ValueError("invalid slug")
    return value


